/**
 * UTC timestamp 문자열을 KST Date 객체로 변환
 * @param {string|Date|number} value
 * @returns {Date|null}
 * 예) "2026-01-16 06:54:23 UTC"
 */
export const parseUtcToKstDate = (value) => {
	if (!value) return null

	// Date, number 는 그대로 처리
	if (value instanceof Date) {
		return new Date(value.getTime() + 9 * 60 * 60 * 1000)
	}

	if (typeof value === 'number') {
		return new Date(value + 9 * 60 * 60 * 1000)
	}

	// "2026-01-16 06:54:23 UTC" → ISO
	const iso = String(value)
		.replace(' UTC', 'Z')
		.replace(' ', 'T')

	const utcDate = new Date(iso)
	if (isNaN(utcDate)) return null

	return new Date(utcDate.getTime() + 9 * 60 * 60 * 1000)
}

